from collections import deque

def get_divisors(n):
    divs = set()
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    if n >= 2:
        divs.add(n)
    return divs

def bfs_moves(start, target):
    if start == target:
        return 0

    queue = deque([(start, 0)])
    visited = {start}

    # Limiting the search space for intermediate numbers X. 
    # Since we are only checking up to F=10, we can assume intermediate numbers 
    # won't stray extremely far before returning to the target area.
    # Let's enforce a pragmatic limit, say 3*target or 50, whichever is smaller, 
    # unless the start number forces us higher.
    max_search_bound = max(target + 10, start + 10)

    while queue:
        current_n, moves = queue.popleft()

        # 1. Divisors (X | N)
        divs = get_divisors(current_n)
        for X in divs:
            for next_n in [X + 1, X - 1]:
                if next_n == target:
                    return moves + 1
                if next_n not in visited and abs(next_n) <= max_search_bound:
                    visited.add(next_n)
                    queue.append((next_n, moves + 1))

        # 2. Multiples (N | X)
        k = 2
        while True:
            X = current_n * k

            # Pruning: If X is too large, and we are not immediately aiming for the target, stop.
            if abs(X) > max_search_bound * 2 and moves > 5: # A generous cap for early exit
                break

            for next_n in [X + 1, X - 1]:
                if next_n == target:
                    return moves + 1
                if next_n not in visited and abs(next_n) <= max_search_bound * 2:
                    visited.add(next_n)
                    queue.append((next_n, moves + 1))

            k += 1
            if k > 100: # Safety break for large multiplication chains
                 break

    return -1 # Unreachable

# Test cases for S, F up to 10
tests = []
for S in range(2, 11):
    for F in range(2, 11):
        if S != F:
            tests.append((S, F))

results = {}
print("S,F,Moves")
for S, F in tests:
    moves = bfs_moves(S, F)
    print(f"{S},{F},{moves}")
    results[(S, F)] = moves

